const lead = $('Get Lead').first().json;

// Collect all unique products
const products = [];

if (lead.Primary_Product_Interest__c) {
  products.push(lead.Primary_Product_Interest__c);
}

if (lead.Products_of_Interest__c) {
  products.push(...lead.Products_of_Interest__c.split(';'));
}

// Remove duplicates
const uniqueProducts = [...new Set(products)];

// Build product conditions (Primary only)
const productConditions = uniqueProducts
  .map(product => `(Product_Interest__c = '${product}')`)
  .join(' OR ');

return {
  productConditions,
  allProducts: uniqueProducts.join(', ')
};

