// n8n Code node script for round-robin lead assignment

// Get input data from previous node
const inputData = $input.all().map(item => item.json);

function assignLead(users) {
  // Create a working copy of the data
  const updatedUsers = users.map(user => ({ ...user }));

  let assignedUser = null;

  // Calculate total leads (Leads + SkippedOOOLeads) for each user
  const usersWithTotal = updatedUsers.map(user => ({
    ...user,
    totalLeads: (user.Leads || 0) + (user.SkippedOOOLeads || 0)
  }));

  // Sort by totalLeads (ascending), then by row_number (ascending) for tie-breaking
  const sortedUsers = [...usersWithTotal].sort((a, b) => {
    if (a.totalLeads !== b.totalLeads) {
      return a.totalLeads - b.totalLeads;
    }
    return a.row_number - b.row_number;
  });

  // Find the user to assign the lead to
  for (const sortedUser of sortedUsers) {
    // Find the corresponding user in our updatedUsers array
    const userIndex = updatedUsers.findIndex(u => u.row_number === sortedUser.row_number);
    const user = updatedUsers[userIndex];

    // Check if user is OOO
    const isOOO = user.OOO && user.OOO.trim() !== '';

    if (isOOO) {
      // Increment SkippedOOOLeads and continue looking
      updatedUsers[userIndex].SkippedOOOLeads = (user.SkippedOOOLeads || 0) + 1;
    } else {
      // This user gets the lead
      updatedUsers[userIndex].Leads = (user.Leads || 0) + 1;
      assignedUser = user.Email;
      break;
    }
  }

  // Remove the temporary totalLeads property from output
  const cleanedUsers = updatedUsers.map(({ totalLeads, ...rest }) => rest);

  return {
    updatedUsers: cleanedUsers,
    assignedTo: assignedUser
  };
}

// Run the assignment
const result = assignLead(inputData);

// Return in n8n format
return {
  json: {
    assignedTo: result.assignedTo,
    updatedUsers: result.updatedUsers
  }
};

let data = {}

if (typeof $('Consolidate Data').first().json.output === 'string') {
  data = { output: JSON.parse($('Consolidate Data').first().json.output) }
} else {
  data = $('Consolidate Data').first().json
}

return {...data}

/**
 * n8n Code node (JavaScript)
 *
 * Local Government is identified by Account.Industry = "Local Government"
 * (was previously Industry_Segmentation__c LIKE 'GOV-LOC-*').
 *
 * Website and Web Accessibility leads for Local Government route directly to CP.
 *
 * Existing MarkOps override still applies to:
 * - scoped leads in target segmentations
 * - except the Local Government carveout for Websites + Accessibility
 */

function norm(v) {
  if (v === null || v === undefined) return "";
  return String(v).trim();
}

function normLower(v) {
  return norm(v).toLowerCase();
}

function truthyStatus(v) {
  const s = normLower(v);
  return (
    s === "true" ||
    s === "yes" ||
    s === "y" ||
    s === "customer" ||
    s === "active" ||
    s === "current" ||
    s === "1"
  );
}

/**
 * Exact matching for picklists / multi-select picklists.
 * Prevents "Accessibility" from matching "PDF Accessibility".
 */
function splitMultiSelect(listLike) {
  const s = norm(listLike);
  if (!s) return [];
  return s
    .split(";")
    .map((x) => x.trim())
    .filter(Boolean);
}

function containsValue(listLike, value) {
  const target = normLower(value);
  return splitMultiSelect(listLike).some((v) => normLower(v) === target);
}

/**
 * Try to find the opp array regardless of exact key name.
 */
function getOppArray(rootJson) {
  const candidateKeys = [
    "Opportunities",
    "OpportunityRecords",
    "records",
    "opps",
    "opportunities",
  ];

  for (const k of candidateKeys) {
    if (Array.isArray(rootJson?.[k])) return rootJson[k];
  }

  if (Array.isArray(rootJson)) return rootJson;
  return [];
}

function isWebsiteOpp(opp) {
  return (
    containsValue(opp?.Product_Interest__c, "CivicEngage") ||
    containsValue(opp?.Secondary_Product_of_Interest__c, "CivicEngage")
  );
}

const STREAMLINE_SEGMENTATIONS = new Set([
  // Special District
  "GOV-SPC-ELECTIONS",
  "GOV-SPC-FIRE",
  "GOV-SPC-FIRE-VOL",
  "GOV-SPC-FLOOD",
  "GOV-SPC-HEALTH",
  "GOV-SPC-LIBRARIES",
  "GOV-SPC-MILITARY",
  "GOV-SPC-NATURALRES",
  "GOV-SPC-TRANSPORT",
  "GOV-SPC-UTILITIES",
  "GOV-SPC-UTILITIES-COOP",
  "GOV-SPC-OTHER",

  // EDU / K12
  "EDU-PUB-DISTRICT",
  "EDU-PUB-SCHOOLK12",
  "EDU-PUB-CHARTER",
  "EDU-PUB-HIGHERED",
  "EDU-PRI-DISTRICT",
  "EDU-PRI-SCHOOLK12",
  "EDU-PRI-HIGHERED",
  "EDU-SRV",
  "EDU-AGENCY",

  // Healthcare
  "HEALTH-HOSP",
  "HEALTH-HOSP-FOIA",
  "HEALTH-HOSP-NONFOIA",
  "HEALTH-LTC",
  "HEALTH-SRV",

  // Commercial
  "COM-FIN",
  "COM-LEGAL",
  "COM-MANU",

  // Tribal / Non-profit proxy per MarkOps
  "OTH-OTH",
]);

function getSegmentationBucket(seg) {
  if (!seg) return "";

  if (seg.startsWith("GOV-SPC-")) return "Special District";
  if (seg.startsWith("EDU-")) return "Education";
  if (seg.startsWith("HEALTH-")) return "Healthcare";
  if (seg.startsWith("COM-")) return "Commercial";
  if (seg === "OTH-OTH") return "Tribal / Non-profit";

  return "";
}

// --- Begin main ---
const item0 = $('Get an account').first().json;
const lead = $("Get Lead").first().json;

// Account fields
const industrySegmentation = norm(item0.Industry_Segmentation__c);
const accountIndustry = norm(item0.Industry);

const populationRaw = item0.Population__c;
const accountPopulation = Number(populationRaw);
const hasPopulation = Number.isFinite(accountPopulation);

const isWebsitesCustomer = truthyStatus(item0.CivicEngage__c);
const isAccessibilityCustomer = truthyStatus(item0.Accessibility__c);

// Lead fields
const leadPrimaryPOI = norm(lead.Primary_Product_Interest__c);
const leadPOI = norm(lead.Products_of_Interest__c);

// Lead type detection
const isWebsiteLead =
  containsValue(leadPrimaryPOI, "CivicEngage") ||
  containsValue(leadPOI, "CivicEngage");

const isWebAccessibilityLead =
  containsValue(leadPrimaryPOI, "Accessibility") ||
  containsValue(leadPOI, "Accessibility");

const isPDFAccessibilityLead =
  containsValue(leadPrimaryPOI, "PDF Accessibility") ||
  containsValue(leadPOI, "PDF Accessibility");

const isScopedLead =
  isWebsiteLead || isWebAccessibilityLead || isPDFAccessibilityLead;

// Local Government carveout — now driven by Industry, not Industry_Segmentation__c
const isLocalGovernment = normLower(accountIndustry) === "local government";
const isLocalGovWebsiteOrAccessibilityLead =
  isLocalGovernment && (isWebsiteLead || isWebAccessibilityLead);

if ($('LPA Agent - Qualification').first().json.output.action.includes("UNQUAL")) {
  return [
    {
      json: {
        ...item0,
        route_bucket: "CP",
        route_reason: "Unqualified lead.",
      },
    },
  ];
}

if (!isScopedLead) {
  return [
    {
      json: {
        ...item0,
        route_bucket: "CP",
        route_reason:
          "Not a Websites, Accessibility, or PDF Accessibility lead (default CP).",
      },
    },
  ];
}

// Opp scan — opportunities are fetched by the upstream 'Perform a query' node
// (SOQL on the account's opps); the 'Get an account' record does NOT carry them.
// FIX: getOppArray(item0) always returned [] (account record has no opp array), so
// hasWebsiteEcosystemOpp was permanently false and the website-opp -> CP branch was dead.
const opps = $('Perform a query').all()
  .map((i) => i.json)
  .filter((o) => o && o.Id);
const websiteOpps = opps.filter(isWebsiteOpp);
const hasWebsiteEcosystemOpp = websiteOpps.length > 0;

// New segmentation-based rule
const isStreamlineSegmentation =
  STREAMLINE_SEGMENTATIONS.has(industrySegmentation);

const segmentationBucket = getSegmentationBucket(industrySegmentation);

// Legacy fallback logic
const isGovernment = normLower(accountIndustry) === "government";
const popGte50k = hasPopulation && accountPopulation >= 50000;
const popLt50k = hasPopulation && accountPopulation < 50000;

function getLeadTypeLabel() {
  const labels = [];
  if (isWebsiteLead) labels.push("Websites");
  if (isWebAccessibilityLead) labels.push("Accessibility");
  if (isPDFAccessibilityLead) labels.push("PDF Accessibility");
  return labels.join(" + ");
}

let route_bucket = "CP";
let route_reason = "";
const leadTypeLabel = getLeadTypeLabel();

/**
 * Decision tree:
 * 1) Local Government Websites / Accessibility carveout -> CP
 * 2) New MarkOps rule: other scoped lead + target segmentation -> Streamline
 * 3) Else preserve prior behavior as fallback
 */
if (isLocalGovWebsiteOrAccessibilityLead) {
  route_bucket = "CP";
  route_reason =
    `${leadTypeLabel} lead + Local Government industry -> CP per standard routing rule.`;
} else if (isStreamlineSegmentation) {
  route_bucket = "Streamline";
  route_reason =
    `${leadTypeLabel} lead + ${segmentationBucket || industrySegmentation} segmentation -> Streamline per MarkOps rule.`;
} else if (hasWebsiteEcosystemOpp) {
  route_bucket = "CP";
  route_reason =
    `${leadTypeLabel} lead + open website ecosystem opp found (CivicEngage present on at least one opp).`;
} else if (isWebsitesCustomer && isAccessibilityCustomer) {
  route_bucket = "CP";
  route_reason =
    `${leadTypeLabel} lead + CP Website & Accessibility customer.`;
} else if (!isWebsitesCustomer) {
  if (isGovernment && popGte50k) {
    route_bucket = "Streamline";
    route_reason =
      `${leadTypeLabel} lead + Government >= 50k + not CP Website customer.`;
  } else if (isGovernment && (popLt50k || !hasPopulation)) {
    route_bucket = "Streamline";
    route_reason =
      `${leadTypeLabel} lead + Government < 50k (or unknown pop) + not CP Website customer.`;
  } else {
    route_bucket = "Streamline";
    route_reason =
      `${leadTypeLabel} lead + non-website customer fallback -> Streamline.`;
  }
} else {
  route_bucket = "CP";
  route_reason =
    `${leadTypeLabel} lead + Websites customer, but no website opp found; default CP.`;
}

return [
  {
    json: {
      ...item0,
      route_bucket,
      route_reason,
      _routing_debug: {
        leadPrimaryPOI,
        leadPOI,
        isWebsiteLead,
        isWebAccessibilityLead,
        isPDFAccessibilityLead,
        isScopedLead,
        isLocalGovernment,
        isLocalGovWebsiteOrAccessibilityLead,
        industry: accountIndustry,
        industrySegmentation,
        segmentationBucket,
        isStreamlineSegmentation,
        accountPopulation: hasPopulation ? accountPopulation : null,
        isWebsitesCustomer,
        isAccessibilityCustomer,
        opp_count: opps.length,
        website_opp_count: websiteOpps.length,
        website_opp_ids: websiteOpps.map((o) => o.Id).filter(Boolean),
      },
    },
  },
];

// AUTO-GENERATED by build/bundleRoutingNode.js from src/lib/helpers.js + src/routingTree.js.
// Do NOT edit by hand — edit the src/ files (they are unit-tested) and re-run the bundler.

/**
 * Shared deterministic helpers for the LPA routing migration.
 *
 * norm / normLower / splitMultiSelect / containsValue are copied verbatim in
 * spirit from the existing `StreamlineRoutingRules` code node so picklist
 * matching behaves identically across the workflow. In particular,
 * containsValue does EXACT (case-insensitive) matching of each ';'-delimited
 * token, which is what prevents "Accessibility" from matching "PDF Accessibility".
 */

function norm(v) {
  if (v === null || v === undefined) return '';
  return String(v).trim();
}

function normLower(v) {
  return norm(v).toLowerCase();
}

/** Split a picklist / multi-select picklist value into exact tokens. */
function splitMultiSelect(listLike) {
  const s = norm(listLike);
  if (!s) return [];
  return s
    .split(';')
    .map((x) => x.trim())
    .filter(Boolean);
}

/** True iff `value` exactly (case-insensitively) equals one of the tokens in listLike. */
function containsValue(listLike, value) {
  const target = normLower(value);
  if (!target) return false;
  return splitMultiSelect(listLike).some((v) => normLower(v) === target);
}

/**
 * True iff any of the requested products exactly matches a token in the
 * record's picklist field. `products` is an array of Product_Interest__c
 * strings from Opportunity Product Map (allProducts split on ", ").
 */
function matchesAnyProduct(fieldValue, products) {
  return (products || []).some((p) => containsValue(fieldValue, p));
}

/** True iff the action string is any UNQUALIFIED_* variant (mirrors the workflow's `contains "UNQUAL"`). */
function isUnqualifiedAction(action) {
  return norm(action).includes('UNQUAL');
}

/**
 * True iff `dateStr` (a Salesforce date "YYYY-MM-DD" or ISO) is non-null and
 * falls within `days` days at or before `today`. `today` is an ISO date string
 * passed in for determinism (n8n supplies DateTime.now()). Future dates count
 * as "within" as well (recent activity), matching the loose "within 30 days" intent.
 */
function isWithinDays(dateStr, today, days) {
  const s = norm(dateStr);
  if (!s) return false;
  const d = new Date(s);
  const t = new Date(norm(today));
  if (Number.isNaN(d.getTime()) || Number.isNaN(t.getTime())) return false;
  const diffDays = (t.getTime() - d.getTime()) / (1000 * 60 * 60 * 24);
  return diffDays <= days; // includes future (diff negative) and up to `days` in the past
}

/** Cheap SFDC Id format check (15 or 18 char alphanumeric). Used on IDs returned by remaining agents. */
function isValidSfId(id) {
  return /^[a-zA-Z0-9]{15,18}$/.test(norm(id));
}

/**
 * Classify an Engagement Record owner's Salesforce User Role → SDR | AE | AM | OTHER.
 * Order matters: match the leading "SDR" token FIRST (EAM appears inside SDR role names
 * like "SDR - EAM 1" as a segment tag, so never key on the 'eam' substring alone).
 * Shared by the routing tree (AE/AM close-exemption) and streamline (erCloseDisposition).
 */
function classifyOwnerRole(roleName) {
  const r = norm(roleName);
  if (/^SDR\b/i.test(r)) return 'SDR'; // "SDR - …", "SDR - EAM 1", "SDR Manager - …"
  if (/account executive/i.test(r)) return 'AE'; // "Account Executive DocAccess 1"
  if (/^enterprise account manager\b/i.test(r) || /\bCSM\b/i.test(r) || /^sales\s*-\s*AM\b/i.test(r)) return 'AM';
  return 'OTHER';
}

/**
 * evaluateRoutingTree — consolidated Conditions 1–7.
 *
 * Replaces four LLM agents (Simple Existing, Existing, Customer, Routing) with
 * one deterministic decision tree. Pure function: plain objects in, plain
 * objects out, no n8n and no Salesforce in the loop.
 *
 * Source of truth: prompts/03-simple-existing.md, 04-existing.md,
 * 05-customer.md, 06-routing.md. See docs/routing-tree-mapping.md for the
 * rule-by-rule mapping and PROGRESS.md for the input/output contract.
 *
 * @param {object} state  Envelope + context:
 *   { action, ids:{parent_account,target_account,contact,related_opportunity,
 *       related_engagement_record,related_product_instance,engagement_record_needs_closing},
 *     contact_updates, reasoning:[], reason,
 *     products:[string], isStateAccount:bool, isEgmNamed:bool }
 * @param {object} sf  Salesforce records already fetched by upstream nodes:
 *   { parentWbdOpps:[{Id,Product_Interest__c,Secondary_Product_of_Interest__c,contactRoleContactIds:[]}],
 *     targetErs:[{Id,Name,OwnerId,ownerUserRoleName,Product_Interest__c,Secondary_Product_of_Interest__c,IsClosed,LastActivityDate}],
 *     productInstances:[{Id,Product_Suite__c,UNI_Status__c,Account__c}] }
 * @param {object} opts  { today: 'YYYY-MM-DD', cond5Require30d?: bool }
 * @returns {{action,ids,contact_updates,reasoning,reason}}
 */

const ACTION = {
  CONVERT_TO_EXISTING_SALES_OPP: 'CONVERT_TO_EXISTING_SALES_OPP',
  CONVERT_TO_EXISTING_ER_WITH_ACTIVITY: 'CONVERT_TO_EXISTING_ER_WITH_ACTIVITY',
  CLOSE_INACTIVE_ER_PASS_TO_INBOUND: 'CLOSE_INACTIVE_ER_PASS_TO_INBOUND',
  ASSIGN_TO_SAME_INBOUND_SDR: 'ASSIGN_TO_SAME_INBOUND_SDR',
  ASSIGN_TO_INBOUND_SDR_ROUND_ROBIN: 'ASSIGN_TO_INBOUND_SDR_ROUND_ROBIN',
  NOTIFY_CSM_EAM_CONVERT_TO_CONTACT: 'NOTIFY_CSM_EAM_CONVERT_TO_CONTACT',
  CREATE_NEW_CONTACT_NO_MATCH: 'CREATE_NEW_CONTACT_NO_MATCH',
  PAUSE_AT_WORKING_STATUS: 'PAUSE_AT_WORKING_STATUS',
  QUALIFIED: 'QUALIFIED',
};

const EMPTY_IDS = {
  parent_account: '',
  target_account: '',
  related_opportunity: '',
  related_engagement_record: '',
  contact: '',
  related_product_instance: '',
  engagement_record_needs_closing: '',
};

function normalizeIds(ids) {
  return { ...EMPTY_IDS, ...(ids || {}) };
}

// Inbound/EAM SDR ownership by the ER owner's Salesforce User Role (user decision: precise
// user-role conventions, confirmed predictable). "starts with SDR AND tagged Inbound/EAM" —
// this cleanly separates an EAM *SDR* (`SDR - EAM 1`) from an Enterprise Account *Manager*
// (`Enterprise Account Manager - West`), which the ER title conflated (see exec 138038).
function isInboundSdr(er) {
  const r = norm((er || {}).ownerUserRoleName);
  return /^SDR\b/i.test(r) && /inbound/i.test(r);
}
function isEamSdr(er) {
  const r = norm((er || {}).ownerUserRoleName);
  return /^SDR\b/i.test(r) && /\beam\b/i.test(r);
}
// REQ-17-22: an ER owned by an Account Executive or (Enterprise) Account Manager — NOT an SDR.
// Such reps are actively working the deal, so their ER is exempt from the inactivity-close.
function isAeAm(er) {
  const cls = classifyOwnerRole((er || {}).ownerUserRoleName);
  return cls === 'AE' || cls === 'AM';
}

/** Order ERs deterministically: most recent LastActivityDate first, tie-break by Id. */
function byRecentActivity(a, b) {
  const da = a.LastActivityDate ? new Date(a.LastActivityDate).getTime() : -Infinity;
  const db = b.LastActivityDate ? new Date(b.LastActivityDate).getTime() : -Infinity;
  if (da !== db) return db - da;
  return norm(a.Id).localeCompare(norm(b.Id));
}

function evaluateRoutingTree(state, sf, opts) {
  const options = opts || {};
  const today = options.today;
  // Cond 5 recency: the prompt PROSE says "LastActivityDate within 30 days" (identical to
  // Cond 4's prose); only the mandated SOQL omitted the clause. Per user ("mimic the squo"),
  // apply the 30-day check by DEFAULT. Pass cond5Require30d:false to fall back to query-literal.
  const cond5Require30d = options.cond5Require30d !== false;

  const incoming = norm(state.action);
  const products = Array.isArray(state.products) ? state.products : [];
  const isMultipleProducts = products.length > 1;
  const isStateAccount = state.isStateAccount === true;

  const ids = normalizeIds(state.ids);
  const contact_updates = state.contact_updates || {};
  const reasoning = Array.isArray(state.reasoning) ? [...state.reasoning] : [];
  const push = (cond, msg) => reasoning.push(`[${cond}] ${msg}`);

  const done = (action, reason) => ({
    action,
    ids,
    contact_updates,
    reasoning,
    reason: reason !== undefined ? reason : state.reason,
  });

  const records = sf || {};
  const parentWbdOpps = records.parentWbdOpps || [];
  const targetErs = (records.targetErs || []).filter((e) => e && e.IsClosed !== true);
  const productInstances = records.productInstances || [];

  // ── SHORT-CIRCUIT (single guard; replaces five per-agent pass-through gates) ──
  if (isUnqualifiedAction(incoming) || incoming === ACTION.PAUSE_AT_WORKING_STATUS) {
    push('SHORT_CIRCUIT', `Input action ${incoming} is terminal (UNQUALIFIED/PAUSE); passing through unchanged.`);
    return done(incoming);
  }

  let action = incoming; // working action
  let decided = false; // a Condition 2–6 matched

  // A lead is "routable" (runs the ownership checks) when it is QUALIFIED, OR when it is
  // CREATE_NEW_CONTACT_NO_MATCH (a contact was just created upstream — the `ContactIdMap`
  // node deliberately stamps ids.action:"QUALIFIED", and the live workflow routes these as
  // QUALIFIED; CREATE_NEW_CONTACT_NO_MATCH never survives as a final action in the corpus).
  const strayQualified = state.ids && state.ids.action === ACTION.QUALIFIED;
  const isRoutable =
    incoming === ACTION.QUALIFIED ||
    incoming === ACTION.CREATE_NEW_CONTACT_NO_MATCH ||
    strayQualified === true;

  // ── Conditions 2–6 run for routable leads (QUALIFIED or created-contact) ──
  if (isRoutable) {
    // ── CONDITION TWO: existing Sales Opportunity at PARENT (WBD Standard) ──
    const stateNote = isStateAccount
      ? ' (STATE account: also require the input Contact to be on the Opportunity via OpportunityContactRole)'
      : '';
    const cond2Match = parentWbdOpps.find((opp) => {
      const productMatch = matchesAnyProduct(opp.Product_Interest__c, products);
      if (!productMatch) return false;
      if (isStateAccount) {
        const roles = opp.contactRoleContactIds || [];
        return ids.contact && roles.map(norm).includes(norm(ids.contact));
      }
      return true;
    });
    if (cond2Match) {
      ids.related_opportunity = cond2Match.Id;
      action = ACTION.CONVERT_TO_EXISTING_SALES_OPP;
      decided = true;
      push('COND_2', `Open WBD Standard Opportunity ${cond2Match.Id} at parent matches requested product${stateNote}. -> CONVERT_TO_EXISTING_SALES_OPP.`);
    } else {
      push('COND_2', `No open WBD Standard Opportunity at parent matched the requested product(s)${stateNote}. Continue.`);
    }

    // ── CONDITION THREE: open OUTBOUND Engagement Record on TARGET agency, product match ──
    // Cond 3 handles OUTBOUND ERs only. Inbound/EAM SDR ERs (→ Cond 4/5) are identified by the
    // owner's Salesforce User Role (precise conventions), so exclude them here.
    if (!decided) {
      const cond3Candidates = targetErs.filter(
        (er) =>
          matchesAnyProduct(er.Product_Interest__c, products) &&
          !isInboundSdr(er) &&
          !isEamSdr(er)
      );
      // REQ-17-22 (AE/AM exemption): an ER owned by an Account Executive / Account Manager is
      // exempt from the inactivity-close — treat it as convertible (attach) regardless of activity,
      // so it routes through the CONVERT branch (PassInboundLead handles notification; deal
      // attribution is handled Salesforce-side). SDR/other-owned inactive ERs still close.
      const convertible = cond3Candidates
        .filter((er) => isWithinDays(er.LastActivityDate, today, 30) || isAeAm(er))
        .sort(byRecentActivity);
      if (convertible.length > 0) {
        const er = convertible[0];
        ids.related_engagement_record = er.Id;
        action = ACTION.CONVERT_TO_EXISTING_ER_WITH_ACTIVITY;
        decided = true;
        const why = isWithinDays(er.LastActivityDate, today, 30)
          ? `has activity within 30 days (LastActivityDate ${norm(er.LastActivityDate)})`
          : `is owned by an AE/AM ("${norm(er.ownerUserRoleName)}") and is exempt from the inactivity-close (REQ-17-22)`;
        push('COND_3', `Open ER ${er.Id} on target agency matches product and ${why}. -> CONVERT_TO_EXISTING_ER_WITH_ACTIVITY.`);
      } else if (cond3Candidates.length > 0) {
        const er = [...cond3Candidates].sort(byRecentActivity)[0];
        ids.related_engagement_record = er.Id;
        action = ACTION.CLOSE_INACTIVE_ER_PASS_TO_INBOUND;
        decided = true;
