// ── STEP 2: geography ───────────────────────────────────────────────────────
function determineGeography(lead) {
  const addr = lead.Address || {};
  const country = normLower(addr.country);
  const cc = normLower(addr.countryCode);
  const domain = emailDomain(lead.Email);
  const tld = domain.split('.').pop();
  const phone = norm(lead.Phone);

  const signals = [];
  // address
  let addrSig = null;
  if (/united states|u\.s\.a|^usa$|^us$/.test(country) || cc === 'us') addrSig = 'US';
  else if (/canada/.test(country) || cc === 'ca') addrSig = 'CA';
  else if (country) addrSig = 'FOREIGN';
  if (addrSig) signals.push(`address=${addrSig}`);

  // phone country code: NANP (+1) => US/CA; other explicit +cc => FOREIGN
  let phoneSig = null;
  if (phone) {
    const digits = phone.replace(/[^\d+]/g, '');
    if (/^\+?1\d{10}$/.test(digits) || /^\d{10}$/.test(digits)) phoneSig = 'NANP';
    else if (/^\+/.test(digits) && !/^\+1/.test(digits)) phoneSig = 'FOREIGN';
    if (phoneSig) signals.push(`phone=${phoneSig}`);
  }

  // email TLD: .ca => CA; 2-letter ccTLD not in neutral set => FOREIGN
  let tldSig = null;
  if (tld === 'ca') tldSig = 'CA';
  else if (tld && tld.length === 2 && !NEUTRAL_TLDS.has(tld)) tldSig = 'FOREIGN';
  else if (/\.(ac|edu|gov)\.[a-z]{2}$/.test(domain) && !/\.us$/.test(domain)) tldSig = 'FOREIGN'; // e.g. .ac.zw
  if (tldSig) signals.push(`emailTld=${tldSig}`);

