  const anyCA = [addrSig, tldSig].includes('CA');
  const anyUS = addrSig === 'US' || phoneSig === 'NANP';

  // A clear FOREIGN signal wins (matches corpus: US address + foreign phone/ccTLD -> GEO).
  if (foreign) return { country: 'OTHER', action: ACT.GEO, note: `Foreign geography signal present (${signals.join(', ')}) -> outside US/Canada.` };
