  if (anyUS) return { country: 'US', action: null, note: `US detected (${signals.join(', ')}).` };
  return { country: 'UNKNOWN', action: ACT.PAUSE, note: `Insufficient/conflicting location signals (${signals.join(', ') || 'none'}) -> pause for review.` };
