  const govCompany = /\b(city of|county of|town of|village of|borough of|township|sheriff|police department|fire department|public works|municipal|department of)\b/.test(company);
  const k12Domain = /\.k12\./.test(domain) || /\bk12\b/.test(domain);
  const k12Company = /\b(school district|public schools|elementary school|middle school|high school|isd\b|unified school)\b/.test(company);
  const eduDomain = /\.edu$/.test(domain);
  const higherCompany = /\b(university|college|community college)\b/.test(company);

  if (govDomain || govCompany) return { orgType: ORG.GOVERNMENT, confidence: 'high', needWebVerify: false };
  if (k12Domain || k12Company) return { orgType: ORG.EDU_K12, confidence: 'high', needWebVerify: false };
  if (eduDomain || higherCompany) return { orgType: ORG.EDU_HIGHER, confidence: 'medium', needWebVerify: true };
